510  get_packet_body_mpi(pgp_packet_body_t *body, pgp_mpi_t *val)
   511  {
   512      uint16_t bits;
   513      size_t   len;
   514
   515      if (!get_packet_body_uint16(body, &bits)) {
   516          return false;
   517      }
   518
   519      len = (bits + 7) >> 3;
   520      if (len > PGP_MPINT_SIZE) {
   521          RNP_LOG("too large mpi");
   522          return false;
   523      }
   524      if (len == 0) {
   525          RNP_LOG("0 mpi");
   526          return false;
   527      }
   528      if (!get_packet_body_buf(body, val->mpi, len)) {
   529          RNP_LOG("failed to read mpi body");
   530          return false;
   531      }
   532      /* check the mpi bit count */
   533      unsigned hbits = bits & 7 ? bits & 7 : 8;
   534      if ((((unsigned) val->mpi[0] >> hbits) != 0) ||
   535          !((unsigned) val->mpi[0] & (1U << (hbits - 1)))) {
   536          RNP_LOG("Warning! Wrong mpi bit count: got %d, but high byte is %d",
   537                  (int) bits,
   538                  (int) val->mpi[0]);
   539      }
   540
   541      val->len = len;
   542      return true;
   543  }
